public class JSTypeRegistry_getType_TriageGen1Test {

    private JSTypeRegistry registry;
    private ErrorReporter errorReporter;
    private StaticScope<JSType> mockScope;

    @Before
    public void setUp() {
        errorReporter = Mockito.mock(ErrorReporter.class);
        registry = new JSTypeRegistry(errorReporter);
        mockScope = Mockito.mock(StaticScope.class);
    }

    /**
     * Tests that if the type already exists in the registry (via getType(String)),
     * it is returned immediately without creating a new NamedType.
     */
    @Test
    public void testGetType_ExistingType() {
        String typeName = "number";
        // Pre-register a type (using a native type or declared type)
        JSType existingType = registry.getNativeType(JSTypeNative.NUMBER);

        // Note: In the real implementation, getType(String) might return a native type.
        // We use a name that we know the registry can provide.
        JSType result = registry.getType(mockScope, "number", "source.js", 1, 1);

        assertNotNull(result);
        assertEquals("number", result.toString());
        // If it's the native number type, it should match the registry's internal mapping
        assertSame(registry.getNativeType(JSTypeNative.NUMBER), result);
    }

    /**
     * Tests the branch where the type does NOT exist.
     * It should create a new NamedType, put it in unresolvedNamedTypes for the scope, and return it.
     */
    @Test
    public void testGetType_NewNamedType() {
        String typeName = "MyCustomType";
        String sourceName = "test.js";
        int line = 10;
        int charNo = 5;

        // Ensure it's not a known type
        JSType result = registry.getType(mockScope, typeName, sourceName, line, charNo);

        assertNotNull(result);
        // Verify it is indeed a NamedType (via checking name/identity)
        assertEquals(typeName, result.toString());

        // Since we can't directly access the private 'unresolvedNamedTypes' map easily 
        // without reflection, we verify the behavior by calling it again.
        // A second call with the same scope and name should return the same instance.
        JSType result2 = registry.getType(mockScope, typeName, sourceName, line, charNo);
        assertSame("Should return the same instance for the same scope", result, result2);
    }

    /**
     * Tests that different scopes result in different NamedType instances 
     * for the same type name if they are unresolved.
     */
    @Test
    public void testGetType_DifferentScopes() {
        String typeName = "ScopedType";
        StaticScope<JSType> scope1 = Mockito.mock(StaticScope.class);
        StaticScope<JSType> scope2 = Mockito.mock(StaticScope.class);

        JSType type1 = registry.getType(scope1, typeName, "src.js", 1, 1);
        JSType type2 = registry.getType(scope2, typeName, "src.js", 1, 1);

        assertNotNull(type1);
        assertNotNull(type2);
        // They should be different instances because they are mapped to different scopes
        // in the unresolvedNamedTypes map.
        org.junit.Assert.assertNotSame(type1, type2);
    }

    /**
     * Tests that calling getType with a null-returning internal getType(String) 
     * correctly triggers the NamedType creation logic.
     */
    @Test
    public void testGetType_TriggersNamedTypeCreation() {
        // "UnknownType" is definitely not a native type
        String unknownName = "UnknownType";

        JSType type = registry.getType(mockScope, unknownName, "file.js", 5, 5);

        assertNotNull(type);
        // Verify properties of the created NamedType
        // In Rhino, NamedType.toString() usually returns the name.
        assertEquals(unknownName, type.toString());
    }
}
